g$Response)","","#visualize pairs plot of numeric predictors colored by class","numeric_vars \u003c- marketing[, sapply(marketing, is.numeric)]","pairs(numeric_vars, col=marketing$Response)","","#partition the data into training and testing using hold out method","#first set the random seed for repeatability","set.seed(4567)","","# Create an index variable to perform a 70/30 split","trainIndex \u003c- createDataPartition(marketing$Response, p=.7, list=FALSE, times=1)","marketing_train \u003c- marketing[trainIndex, ]","marketing_test \u003c- marketing[-trainIndex, ]","","#logistic Regression using glm","trControl \u003c- trainControl(method = 'none')","","glmFit \u003c- train(Response ~ ., ","                data = marketing_train, ","                method = 'glm', ","                family = 'binomial',","                preProcess = c(\"center\",\"scale\"),","                trControl = trControl)","","glmPredClass \u003c- predict(glmFit, marketing_test)","","#now evaluate the classifier using the confusionMatrix() function","confusionMatrix(glmPredClass, marketing_test$Response, mode=\"everything\")","","#random Forest using rf","trControl \u003c- trainControl(method = 'none')","","rfFit \u003c- train(Response ~ ., ","               data = marketing_train, ","               method = 'rf', ","               preProcess = c(\"center\",\"scale\"),","               trControl = trControl)","","rfPredClass \u003c- predict(rfFit, marketing_test)","","#now evaluate the classifier using the confusionMatrix() function","confusionMatrix(rfPredClass, marketing_test$Response, mode=\"everything\")","","######################################################################","#neural Network using nnet","######################################################################","# Use cross validation to optimize network parameters","trControl \u003c- trainControl(method = 'cv', number = 10)","","nnetFit \u003c- train(Response ~ ., ","                 data = marketing_train, ","    